import java.util.*;

public class Main {
    static String toRoman(int n) {
        int[] vals = {1000,900,500,400,100,90,50,40,10,9,5,4,1};
        String[] syms = {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"};
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < vals.length; i++) {
            while (n >= vals[i]) { sb.append(syms[i]); n -= vals[i]; }
        }
        return sb.toString();
    }
    static int val(char c) {
        switch (c) {
            case 'I': return 1; case 'V': return 5; case 'X': return 10;
            case 'L': return 50; case 'C': return 100; case 'D': return 500; case 'M': return 1000;
            default: return -1;
        }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next().trim();
        int sum = 0;
        for (int i = 0; i < s.length(); i++) {
            int cur = val(s.charAt(i));
            if (cur == -1) { System.out.println("INVALID"); return; }
            int nxt = (i + 1 < s.length()) ? val(s.charAt(i + 1)) : 0;
            if (nxt == -1) { System.out.println("INVALID"); return; }
            if (cur < nxt) sum -= cur; else sum += cur;
        }
        if (sum >= 1 && sum <= 3999 && toRoman(sum).equals(s)) System.out.println(sum);
        else System.out.println("INVALID");
    }
}

