import sys

s = sys.stdin.readline().strip()
mp = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
def to_roman(n):
    table = [(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    res = []
    for v, sym in table:
        while n >= v:
            res.append(sym); n -= v
    return ''.join(res)
if any(c not in mp for c in s):
    print('INVALID')
else:
    total = 0
    for i, c in enumerate(s):
        v = mp[c]
        nxt = mp[s[i+1]] if i + 1 < len(s) else 0
        total += -v if v < nxt else v
    print(total if 1 <= total <= 3999 and to_roman(total) == s else 'INVALID')
